update room_inventory
type_id = #{typeId,jdbcType=INTEGER}, date = #{date,jdbcType=DATE}, total_count = #{totalCount,jdbcType=INTEGER}, reserved_count = #{reservedCount,jdbcType=INTEGER}, locked_count = #{lockedCount,jdbcType=INTEGER}, booked_count = #{bookedCount,jdbcType=INTEGER}, base_price = #{basePrice,jdbcType=DOUBLE}, update_time = now(),
where inventory_id = #{inventoryId,jdbcType=INTEGER}

update room_inventory
set booked_count = booked_count + 1,
    update_time = now()
where type_id = #{typeId,jdbcType=INTEGER}
  and date = #{date,jdbcType=DATE}
  and (total_count - reserved_count - locked_count - booked_count) > 0

update room_inventory
set booked_count = booked_count - 1,
    update_time = now()
where type_id = #{typeId,jdbcType=INTEGER}
  and date = #{date,jdbcType=DATE}
  and booked_count > 0

update room_inventory
set reserved_count = #{reservedCount,jdbcType=INTEGER},
    update_time = now()
where type_id = #{typeId,jdbcType=INTEGER}
  and date = #{date,jdbcType=DATE}
  and (total_count - #{reservedCount,jdbcType=INTEGER} - locked_count - booked_count) >= 0

update room_inventory
set locked_count = #{lockedCount,jdbcType=INTEGER},
    update_time = now()
where type_id = #{typeId,jdbcType=INTEGER}
  and date = #{date,jdbcType=DATE}
  and (total_count - reserved_count - #{lockedCount,jdbcType=INTEGER} - booked_count) >= 0

update room_inventory
set total_count = #{totalCount,jdbcType=INTEGER},
    update_time = now()
where type_id = #{typeId,jdbcType=INTEGER}
  and date = #{date,jdbcType=DATE}
